process:
builder = get_plugin('CidDatasetBuilder')
runner_id = (state.get('runner_id') or 'wf_cid_re_llm_linear').strip()
source = (state.get('source') or 'data/raw/dev.txt').strip()
try:
    size = int(state.get('size') or 20)
except Exception:
    size = 20
tuning_out = (state.get('tuning_out') or '').strip() or None
test_out = (state.get('test_out') or '').strip() or None
wtr = state.get('write_test_remain', True)
if isinstance(wtr, str):
    write_test_remain = wtr.strip().lower() not in ('0', 'false', 'no', '')
else:
    write_test_remain = bool(wtr if wtr is not None else True)
mner = state.get('mirror_ner', True)
if isinstance(mner, str):
    mirror_ner = mner.strip().lower() not in ('0', 'false', 'no', '')
else:
    mirror_ner = bool(mner if mner is not None else True)
if not builder:
    __result__ = {'error': 'CidDatasetBuilder plugin unavailable'}
else:
    try:
        __result__ = builder.build_tuning(
            runner_id,
            source=source,
            size=size,
            tuning_out=tuning_out,
            test_out=test_out,
            write_test_remain=write_test_remain,
            mirror_ner=mirror_ner,
        )
    except Exception as e:
        __result__ = {'error': str(e), 'runner_id': runner_id, 'source': source, 'size': size}
